/**
 * dsh-lan-proxy — 官方 settings 命名空间接线（#276 方案 A 阶段 3 拆出）。
 *
 * 职责：插件在官方 settings 服务中的命名空间（SETTINGS_NS）、minimal 类型面
 * （OwnerScopeLike / SettingsServiceLike / LanProxySettingsHooks）与挂载函数
 * installLanProxySettings。非导出辅助 isUnloading / warnLog 亦归此模块
 * （apply.ts 经 module 导出复用 warnLog，不重复实现）。
 */
import type { Context } from "@deepseek-ai/cordis";
import { errorMessage } from "../../../shared/host-utils.js";
import { Config } from "./config.ts";
import type { LanProxyConfig } from "./config.ts";

/** 本插件在官方 settings 服务中的命名空间。 */
export const SETTINGS_NS = "dsh-lan-proxy";

/**
 * 是否正处于插件自身 fiber 卸载中（区别于「仅丢失 settings 服务」）。
 * 与 shared/settings-namespace.js 同款判据：fiber.state ∈ { unloading, unloaded,
 * disposed }。（包内复刻：coder 规程禁止改 shared/，而 owner scope 写能力需要
 * 拿到 register 返回值，shared 版 hooks 不外露 scope。）
 */
function isUnloading(ctx: unknown): boolean {
  const fiber =
    ctx && typeof ctx === "object" && "fiber" in ctx
      ? (ctx as { fiber?: { state?: unknown } }).fiber
      : undefined;
  const state = fiber && typeof fiber === "object" ? fiber.state : undefined;
  return state === "unloading" || state === "unloaded" || state === "disposed";
}

/** 日志兜底：logger 可能确实没有（极端降级），全部可选调用。 */
export function warnLog(ctx: unknown, message: string): void {
  const logger =
    ctx && typeof ctx === "object" && "logger" in ctx
      ? (ctx as { logger?: { warn?: (...a: unknown[]) => void } }).logger
      : undefined;
  if (typeof logger?.warn === "function") logger.warn(message);
}

/**
 * owner scope 最小类型面（官方 SettingsScope<T> 的子集；仅 import type 无法
 * 从运行时拿到该包，这里按 @deepseek-ai/dsh-settings@0.1.1-rc.2 类型层收窄）。
 */
export interface OwnerScopeLike {
  /** 当前解析值（schema defaults → base → user 层）。 */
  get(): LanProxyConfig;
  /** 提交后异步串行回调，返回 disposer。 */
  watch(cb: (next: LanProxyConfig, prev: LanProxyConfig) => void): () => void;
  /** 增量 merge patch 进 user 层并持久化。 */
  update(patch: object, expectedRevision?: number): Promise<void>;
  /** 整节替换 user 层，缺省键回落 base/schema 默认。 */
  replace(section: object, expectedRevision?: number): Promise<void>;
}

/** settings 服务最小类型面（register/describe）。 */
export interface SettingsServiceLike {
  register(ns: string, schema: unknown, options?: { base?: unknown }): OwnerScopeLike;
  describe(options?: { redactSecrets?: boolean }): Array<{ ns: string; user?: unknown; revision: number }>;
}

/** installLanProxySettings 的 hooks 面（含 onScope：attach 后交出 owner scope）。 */
export interface LanProxySettingsHooks {
  /** 把插件对该命名空间的读取来源指向返回的 scope（`scope.get()`）。 */
  setSource(source: () => LanProxyConfig): void;
  /** 来源切换或命名空间值变化时触发，插件据此刷新/重建转发器。 */
  onChange(): void;
  /** scope attach 后回调（迁移在此执行）；服务缺失时不触发。 */
  onScope(scope: OwnerScopeLike, service: SettingsServiceLike): void;
}

/**
 * 注册插件自有 settings 命名空间并把 owner scope 交给调用方
 * （服务面注入，零包依赖；语义等值复刻官方 installSettingsSection 与
 * shared/installSettingsNamespace——差异仅在把 register 返回的 owner scope
 * 经 onScope 外露，供存量配置迁移写入）。
 *
 * 为什么不用官方 @deepseek-ai/dsh-settings 包：插件运行时沿自身 lib/ 向上
 * 解析不到该包（MODULE_NOT_FOUND），动态 import 会静默失败——与
 * shared/settings-namespace.js 相同的服务面注入方案。
 *
 * @param ctx - 插件宿主端 apply 收到的 cordis 上下文。
 * @param entry - 组合层配置，作为命名空间的 base 层。
 * @param hooks - source 收藏、变更通知与 scope 移交。
 */
export function installLanProxySettings(ctx: Context, entry: LanProxyConfig, hooks: LanProxySettingsHooks): void {
  type InjectFn = (services: string[], fn: (c: any) => void) => void;
  if (typeof (ctx as unknown as { inject?: InjectFn })?.inject !== "function") {
    warnLog(ctx, `${SETTINGS_NS}: ctx.inject 不可用 — 设置命名空间未注册，设置卡降级`);
    return;
  }
  (ctx.inject as unknown as InjectFn)(["settings"], (sctx) => {
    const settings = sctx && (sctx.settings as SettingsServiceLike | undefined);
    if (!settings || typeof settings.register !== "function") {
      warnLog(ctx, `${SETTINGS_NS}: settings 服务缺少 register 能力 — 设置命名空间未注册，设置卡降级`);
      return;
    }
    let scope: OwnerScopeLike;
    try {
      scope = settings.register(SETTINGS_NS, Config, { base: entry });
    } catch (err) {
      warnLog(ctx, `${SETTINGS_NS}: settings.register 失败 — ${errorMessage(err)}`);
      return;
    }
    hooks.onScope(scope, settings);
    hooks.setSource(() => scope.get());
    sctx.effect(() => () => {
      if (isUnloading(ctx)) return;
      hooks.setSource(() => entry);
      hooks.onChange();
    });
    hooks.onChange();
    // 热更新统一走官方 scope.watch（提交后异步串行回调）。
    scope.watch(() => {
      if (isUnloading(ctx)) return;
      hooks.onChange();
    });
  });
}

packages/dsh-lan-proxy/src/index.ts.source:
/**
 * dsh-lan-proxy — 主机端。dsh web UI 的零依赖 LAN 转发器：等回环 web 服务器
 * 绑定后，在 0.0.0.0:<port> 上监听并把 HTTP + WebSocket 转发到
 * 127.0.0.1:<webServer.port>（默认 3080），重写 Host/Origin 使 /api 浏览器
 * 信任围栏接受这些请求。
 *
 * 端口不是固定的：默认 3081，可通过两层途径修改（都实时生效）——
 *   1. GUI 设置卡片（设置 → 插件 → dsh-lan-proxy）：经 loopback HTTP 配置路由
 *      写入官方 settings 命名空间（scope.update/replace），scope.watch 触发热更新；
 *      settings 服务不可解析时自动降级并打 warn 日志。
 *   2. 组合层配置（profile 的 cordis.patch.yml 覆盖 lan-proxy 行的 config，
 *      或启动时 --patch overlay）——作为 settings 命名空间的 base 层生效。
 *
 * 配置单一通道（issue #110）：不再维护自建 `~/.dsh/lan-proxy/config.json` 与
 * RPC state/config 端点；配置一律存官方 settings 存储（settings.register 注册的
 * `dsh-lan-proxy` 命名空间，owner scope get/watch/update/replace）。存量
 * config.json 在 settings 服务 attach 后做一次性 marker 迁移（原子改名
 * `config.json.migrated.bak` 幂等标记 → 校验过滤 → scope.update 增量写入，
 * 失败回滚改名）；此后手改 config.json 不再生效。
 *
 * 激活方式：把本包安装进某个 profile，其 cordis.patch.yml（通过
 * `dsh.bundle.patch` 声明）会插入 `lan-proxy` 这一行：
 *
 *   dsh plugin --profile web add link:<本包路径>
 *
 * 该行是普通 cordis 插件：主机端（exports "."）在宿主进程运行，注入
 * `webServer`，因此只在回环服务器监听后启动，并从 ctx.webServer.port
 * 解析真实上游端口（`--port 0` 与自定义 `--port` 均可用）。
 *
 * 结构（#276 方案 A 阶段 3 拆分）：职责按模块拆分（config / settings /
 * migrate / config-routes / apply），本文件保留插件契约（name/inject 与 apply、
 * 路由表转发）与全部公共符号 re-export（导出面不变，外部消费者从
 * lib/index.js 导入不受影响）。apply 实现于 apply.ts，不 import 本文件。
 */
export const name = "lan-proxy";

/** 等回环 web 服务器绑定并初始化后再启动。 */
export const inject = ["webServer"];

// ------------------------------------------------------------------ 对外 re-export
// 注意：bundle-host 会把 tsc 产物中的子模块全部内联进 lib/index.js 并清理游离 .js，
// smoke/lint 只能从 lib/index.js 导入，故契约与核心模块一律在此 re-export。
// 配置模型与校验（#276 方案 A 阶段 3 拆出：schema / 校验 / 净化 / 类型面）
export { Config, sanitizeSettings, validateSettings } from "./config.ts";
export type { HttpCompressSnapshot, LanProxyConfig, ResolvedConfig, SettingInvalid } from "./config.ts";
// 官方 settings 命名空间接线（#276 方案 A 阶段 3 拆出）
export { SETTINGS_NS, installLanProxySettings } from "./settings.ts";
export type { LanProxySettingsHooks, OwnerScopeLike } from "./settings.ts";
// 存量 config.json 一次性迁移（#276 方案 A 阶段 3 拆出）
export { MIGRATED_BAK_NAME, migrateFileConfig } from "./migrate.ts";
export type { MigrationOutcome } from "./migrate.ts";
// loopback HTTP 配置路由（#276 方案 A 阶段 3 拆出：路由表 + 保存纯函数）
export { ROUTES, applyConfigPatch, buildConfigRoutes } from "./config-routes.ts";
export type { ConfigRouteDeps, PatchResult } from "./config-routes.ts";
// 插件挂载主流程（apply + 转发常量）
export { apply, pluginDir, DEFAULT_WSS_COMPRESS_PATHS } from "./apply.ts";

// 测试面 re-export（smoke 只依赖主入口，避免发布物保留内部模块）
export { createLanProxy, hostnameAllowed, formatAuthority, rewriteHeaders, isLoopbackTarget, DEFAULT_OPTIONS, compressWsPath, isCompressible, resolveCompressionOptions, deflateAllowedByPolicy, DEFAULT_DEFLATE_POLICY } from "./proxy.ts";
export type { ConnStats, DeflatePolicy, LanProxy } from "./proxy.ts";
export { ensureSelfSignedTls, certStillValid, toSanEntry, loadTlsFromFiles, SELF_SIGNED_KEY, SELF_SIGNED_CERT } from "./cert.ts";

packages/dsh-lan-proxy/test/unit-apply.s.source:
// @ts-nocheck
/**
 * dsh-lan-proxy — 宿主端（src/index.ts）结构化单测。
 *
 * 覆盖本批未覆盖热点（fnMap 可命中）：
 * - prepareTls：apply(httpsEnabled: true) → sync() → prepareTls
 * - setSource / onScope：installLanProxySettings 的 hooks 回调
 * - migrateFileConfig / applyConfigPatch：迁移与保存通道边界
 * - isUnloading（包内复刻）：scope.watch 回调内调用
 * - warnLog：settings 服务缺少 register 时调用
 */
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync, readFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
  pluginDir, sanitizeSettings, validateSettings,
  migrateFileConfig, MIGRATED_BAK_NAME, applyConfigPatch, SETTINGS_NS,
  ROUTES, DEFAULT_OPTIONS,
} from "../src/index.ts";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const { createServer } = await import("node:http");

// ===== pluginDir =====
{
  const prev = process.env.DSH_HOME;
  const tmp = mkdtempSync(join(tmpdir(), "dsh-lan-proxy-dir-"));
  process.env.DSH_HOME = tmp;
  const dir = pluginDir();
  assert.ok(dir.endsWith("/lan-proxy"), `pluginDir 结尾 /lan-proxy，实际 ${dir}`);
  assert.ok(dir.startsWith(tmp), `pluginDir 在 DSH_HOME 内，实际 ${dir}`);
  process.env.DSH_HOME = prev;
  rmSync(tmp, { recursive: true, force: true });
}

// ===== sanitizeSettings 更多边界 =====
{
  assert.equal(sanitizeSettings({ wsCompressPaths: "not-array" }), null, "wsCompressPaths 非数组 → null");
  assert.equal(sanitizeSettings({ wsCompressEnabled: "yes" }), null, "wsCompressEnabled 非布尔 → null");
  assert.equal(sanitizeSettings({ httpCompressLevel: -1 }), null, "httpCompressLevel 负值 → null");
  assert.equal(sanitizeSettings({ httpCompressLevel: 1.5 }), null, "httpCompressLevel 非整数 → null");
  assert.deepEqual(sanitizeSettings({}), {}, "空对象 → 空");
}

// ===== validateSettings 更多边界 =====
{
  assert.equal(validateSettings({}), null, "空对象 → null");
  assert.equal(validateSettings({ port: 3081 }), null, "仅端口合法 → null");
  const bad = validateSettings({ enabled: "yes", port: "abc" });
  assert.equal(bad.key, "enabled", "enabled 非法优先");
  const badPaths = validateSettings({ wsCompressPaths: [1, 2] });
  assert.equal(badPaths.key, "wsCompressPaths", "wsCompressPaths 非法检测");
  const badLevel = validateSettings({ httpCompressLevel: 10 });
  assert.equal(badLevel.key, "httpCompressLevel", "httpCompressLevel 非法检测");
  assert.ok(badLevel.hint.includes("0-3"), "hint 含档位范围");
}

// ===== migrateFileConfig 边界（#110） =====
{
  // 非 object JSON：只改名标记、不写入。
  const dir = mkdtempSync(join(tmpdir(), "dsh-lan-proxy-mig-"));
  writeFileSync(join(dir, "config.json"), JSON.stringify(123));
  const outcome = await migrateFileConfig(dir, { async update() { throw new Error("must not be called"); } });
  assert.equal(outcome.skippedCorrupt, true, "number JSON → 只标记不写");
  assert.equal(existsSync(join(dir, MIGRATED_BAK_NAME)), true, "bak 标记存在");
  assert.equal(existsSync(join(dir, "config.json")), false);
  rmSync(dir, { recursive: true, force: true });

  // sanitize 拒绝（含非法值）：整体不写。
  const dir2 = mkdtempSync(join(tmpdir(), "dsh-lan-proxy-mig2-"));
  writeFileSync(join(dir2, "config.json"), JSON.stringify({ port: 99999 }));
  const outcome2 = await migrateFileConfig(dir2, { async update() { throw new Error("must not be called"); } });
  assert.equal(outcome2.migrated, false, "含非法值不写入");
  rmSync(dir2, { recursive: true, force: true });
}

// ===== applyConfigPatch 错误路径（#110） =====
{
  const baseDeps = (over = {}) => ({
    resolve: () => ({ enabled: true }),
    readUser: () => ({ user: {}, revision: 1 }),
    writable: () => true,
    update: async () => {},
    replace: async () => {},
    compress: () => ({ httpCompressEnabled: true, httpCompressLevel: 1, httpCompressMounted: false, httpCompressStats: { compressed: 0, passthrough: 0 } }),
    ...over,
  });
  // settings 服务不可用
  const na = await applyConfigPatch(baseDeps({ writable: () => false }), { patch: {} });
  assert.equal(na.ok, false);
  assert.equal(na.status, 503, "settings 不可用 → 503");
  // 非法 settings
  const invalid = await applyConfigPatch(baseDeps(), { patch: { port: 99999 } });
  assert.equal(invalid.ok, false);
  assert.equal(invalid.code, "invalid");
  // handler 内抛异常 → 500，details 固定文案（P2-2），原文走 logWarn
  const logWarns: string[] = [];
  const broken = await applyConfigPatch(
    baseDeps({ update: async () => { throw new Error("broken-secret"); }, logWarn: (m) => logWarns.push(m) }),
    { patch: { port: 3000 } },
  );
  assert.equal(broken.ok, false);
  assert.equal(broken.status, 500);
  assert.equal(broken.details, "保存失败，请查看服务端日志", "details 不泄露 err.message 原文");
  assert.ok(logWarns.some((m) => m.includes("broken-secret")), "err.message 走服务端日志");
}

// ===== applyConfigPatch tls 成对形态（P2-1） =====
{
  const baseDeps = () => ({
    resolve: () => ({ enabled: true }),
    readUser: () => ({ user: {}, revision: 1 }),
    writable: () => true,
    update: async () => {},
    replace: async () => {},
    compress: () => ({ httpCompressEnabled: true, httpCompressLevel: 1, httpCompressMounted: false, httpCompressStats: { compressed: 0, passthrough: 0 } }),
  });
  // 单边空串混单侧非空字符串 → raw 层拒绝（sanitize 剔除空串后不再绕过成对校验）
  for (const patch of [
    { tlsCertFile: "", tlsKeyFile: "/keep.pem" },
    { tlsCertFile: "/new.pem", tlsKeyFile: "" },
  ]) {
    const mixed = await applyConfigPatch(baseDeps(), { patch });
    assert.equal(mixed.ok, false, `patch=${JSON.stringify(patch)} 应被拒`);
    assert.equal(mixed.code, "tls-pair");
    assert.equal(mixed.status, 400);
  }
}

// ===== apply 集成：TLS 准备 + settings 命名空间（setSource/onScope/isUnloading/warn） =====
// 构造 fake ctx 使 installLanProxySettings 的 inject(["settings"]) 成功：
// settings.register 返回 owner scope（get/watch/update/replace），触发 setSource
// 与 onScope 回调；scope.watch 触发 isUnloading(ctx) 调用。
{
  const applyHome = mkdtempSync(join(tmpdir(), "dsh-lan-proxy-apply-tls-"));
  const prevHome = process.env.DSH_HOME;
  process.env.DSH_HOME = applyHome;
  const routes = [];
  const rpcHandles = [];
  const disposers = [];
  const scopeWatchCbs = [];

  const scope = {
    _val: { port: 0, wsCompressEnabled: false, httpCompressEnabled: false },
    get() { return this._val; },
    async update(patch) { Object.assign(this._val, patch); },
    async replace(section) { this._val = { ...section }; },
    watch(cb) {
      scopeWatchCbs.push(cb);
      // 立即触发一次，使 isUnloading(ctx) 被调用
      cb();
      return () => {};
    },
  };
  const settingsService = {
    register(ns, schema, opts) { return scope; },
    describe() { return [{ ns: SETTINGS_NS, user: {}, revision: 1 }]; },
  };

  const ctx = {
    logger: { info: () => {}, warn: () => {}, error: () => {} },
    webServer: { port: 3080, register(route) { routes.push(route); return () => {}; }, tapIndex() { return () => {}; } },
    inject(services, fn) {
      if (services.includes("connection")) {
        const connectionCtx = {
          connection: { rpc: { handle(channel, h, opts) { rpcHandles.push({ channel, h, opts }); return () => {}; } } },
          effect(fn2) { return fn2(); },
        };
        fn(connectionCtx);
      }
      if (services.includes("settings")) {
        const sctx = {
          settings: settingsService,
          effect(fn2) {
            const d = fn2();
            // 不立即执行 disposer（由外部清理时触发）
            disposers.push(d);
            return d;
          },
        };
        fn(sctx);
      }
    },
    effect(fn) { const d = fn(); if (typeof d === "function") disposers.push(d); return d; },
  };

  const { apply } = await import("../src/index.ts");
  apply(ctx, { host: "127.0.0.1", port: 0, httpsEnabled: true, printBanner: false, wsCompressEnabled: false, httpCompressEnabled: false });

  await sleep(100);

  // 验证 health 路由注册（prepareTls 内部已同步调用）
  const healthRoute = routes.find((r) => r.path === ROUTES.health);
  assert.ok(healthRoute, "health 路由已注册");
  assert.ok(routes.find((r) => r.path === ROUTES.config), "config 路由已注册");
  assert.equal(rpcHandles.length, 0, "RPC 配置通道不再注册");

  // 触发 setSource 后调用 health handler → resolve() → current 已切到 scope.get()
  let healthBody = "";
  healthRoute.handler(
    { method: "GET", socket: { remoteAddress: "127.0.0.1" }, headers: { host: "127.0.0.1:3080" }, url: ROUTES.health },
    { writeHead: () => {}, end: (c) => { healthBody = String(c); } },
  );
  const hp = JSON.parse(healthBody);
  assert.equal(hp.ok, true, "health 200");
  assert.equal(hp.wsCompressEnabled, false, "settings 来源生效（wsCompressEnabled=false 透传）");

  // 执行 lifecycle 清理：触发 scope.watch 的 disposer 与 isUnloading
  for (const d of [...disposers].reverse()) {
    try { d(); } catch {}
  }
  assert.ok(true, "lifecycle 清理不抛错（setSource/isUnloading/warn 路径已覆盖）");

  process.env.DSH_HOME = prevHome;
  rmSync(applyHome, { recursive: true, force: true });
}

